package com.arnavgames.tycoon.core.content

import kotlinx.serialization.Serializable

/**
 * Long-term goals and the Dynasty (content/data/progression.json, generated by tools/content/gen_progression.py).
 * docs/GDD.md §12, docs/ECONOMY.md §9.
 */
@Serializable
data class ProgressionContent(
    val daily: List<MissionTemplateDef>,
    val weekly: List<MissionTemplateDef>,
    val achievements: List<AchievementDef>,
    val ladder: List<LadderStepDef>,
    val weeklyEvents: List<WeeklyEventDef>,
    val seasons: List<SeasonDef>,
    val seasonTrack: List<SeasonTierDef>,
    val charter: List<CharterNodeDef>,
    val traits: List<TraitDef>,
    val challenges: List<ChallengeDef>,
    val config: ProgressionConfig,
) {
    @kotlinx.serialization.Transient val dailyById = daily.associateBy { it.id }
    @kotlinx.serialization.Transient val weeklyById = weekly.associateBy { it.id }
    @kotlinx.serialization.Transient val achievementById = achievements.associateBy { it.id }
    @kotlinx.serialization.Transient val charterById = charter.associateBy { it.id }
    @kotlinx.serialization.Transient val traitById = traits.associateBy { it.id }
    @kotlinx.serialization.Transient val challengeById = challenges.associateBy { it.id }

    companion object {
        val EMPTY = ProgressionContent(emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), emptyList(), ProgressionConfig())
    }
}

/** A daily or weekly mission template. targets: one per chapter band (chapters 1–2, 3–4, 5–8). */
@Serializable
data class MissionTemplateDef(
    val id: String,
    val metric: String,
    val minChapter: Int,
    val title: String,
    val targets: List<Long>,
    val rewardHours: Double,
    val bullion: Long,
    val seasonXp: Long,
)

@Serializable
data class AchievementDef(val id: String, val category: String, val title: String, val description: String, val goal: AchievementGoalDef, val bullion: Long)

/** type: metric, netWorth (log10), chapter, business (id), conglomerates, holding, boardSeats, properties, luxuryOwned,
 * sets, statusTier, fortuneRank, rating (value = rating name), ipo, generation, legacy, heirlooms, challenges, hq. */
@Serializable
data class AchievementGoalDef(val type: String, val metric: String = "", val value: kotlinx.serialization.json.JsonPrimitive? = null, val id: String = "", val log10: Int = 0) {
    val number: Long get() = value?.content?.toLongOrNull() ?: 0L
    val text: String get() = value?.content ?: ""
}

@Serializable
data class LadderStepDef(val day: Int, val cashHours: Double = 0.0, val bullion: Long = 0, val favor: Long = 0)

/** effect: "sector:<id>" (income), or a bonus type (status, rent, dividends, hustle). goals: metrics for the event goals. */
@Serializable
data class WeeklyEventDef(val id: String, val name: String, val description: String, val effect: String, val value: Double, val goals: List<String>)

@Serializable
data class SeasonDef(val id: String, val name: String)

@Serializable
data class SeasonRewardDef(val bullion: Long = 0, val favor: Long = 0, val cashHours: Double = 0.0, val cosmetic: String? = null)

@Serializable
data class SeasonTierDef(val tier: Int, val xp: Long, val free: SeasonRewardDef, val premium: SeasonRewardDef)

/** A Family Charter node: one of two choices for a (branch, tier). Unlocked by banked Legacy and generation. */
@Serializable
data class CharterNodeDef(
    val id: String,
    val branch: String,
    val branchName: String,
    val tier: Int,
    val legacy: Long,
    val generation: Int,
    val name: String,
    val description: String,
    val effect: String,
    val value: Double,
)

@Serializable
data class TraitDef(val id: String, val name: String, val description: String, val effect: String, val value: Double)

@Serializable
data class ChallengeDef(val id: String, val name: String, val description: String, val rule: String, val legacyBonus: Double)

@Serializable
data class IpoConfig(val floats: List<Double> = listOf(0.1, 0.2, 0.3), val valuationMultiple: Double = 2.0, val minChapter: Int = 7)

@Serializable
data class ProgressionConfig(
    val dailyCount: Int = 3,
    val weeklyCount: Int = 5,
    val seasonDays: Int = 28,
    val weekDays: Int = 7,
    val legacyScale: Double = 4.0,
    val legacyExponent: Double = 0.42,
    /** log10 of the peak net worth that earns legacyScale Legacy. Tracks the Chapter 8 goal (TUNING_LOG p11). */
    val legacyNormalizerLog10: Double = 18.0,
    val legacyIncomeFactor: Double = 0.02,
    val legacyIncomeExponent: Double = 0.9,
    /** Heirlooms allowed when passing the crown, by generation (last value repeats). */
    val heirlooms: List<Int> = listOf(1, 1, 2, 2, 3),
    val traitChoices: Int = 3,
    val ipo: IpoConfig = IpoConfig(),
)
